"""The data-plane notebooks: generated by `migrate`, run on AIDP by the user.

Each notebook is self-contained: a PARAMS
cell, the data plan as a literal, the shared helpers and the stage logic, so
the code you open is exactly the code that runs. AIDP types a workspace object
by its extension, and a job's NOTEBOOK_TASK runs an `.ipynb`.

  00_diagnose        reads only; run first
  01_structure       schemas, empty Delta tables (read back), views
  02_copy_dataset    one dataset per run (`dataset` parameter): copy and verify
  03_reconcile       plan versus reality; reads only
"""
from __future__ import annotations

import json
from pathlib import Path

HERE = Path(__file__).parent
CREDENTIAL_NAME = "gcp_bigquery_reader"
CREDENTIAL_KEY = "credentials_b64"

_CREDENTIAL_PARAMS = {"credential-name": CREDENTIAL_NAME, "credential-key": CREDENTIAL_KEY, "key-file": None}
STAGES = {
    "00_diagnose": ("stage_00_diagnose.py", "Diagnose the environment",
                    {**_CREDENTIAL_PARAMS}),
    "01_structure": ("stage_01_structure.py", "Create the structure",
                     {"datasets": None, "external-tables": False, "dry-run": False}),
    "02_copy_dataset": ("stage_02_copy_dataset.py", "Copy one dataset",
                        {"dataset": None, "tables": None, "mode": "skip-existing", "verify": "counts",
                         "dry-run": False, **_CREDENTIAL_PARAMS}),
    "03_reconcile": ("stage_03_reconcile.py", "Reconcile plan and target",
                     {"counts": False}),
}
_NOTES = {
    "datasets": "comma-separated; None = every dataset in the plan",
    "dataset": "REQUIRED: one dataset per run",
    "tables": "comma-separated subset of the dataset; None = all",
    "mode": "skip-existing | overwrite (rewrites rows, never drops) | append",
    "verify": "counts | counts+sums (exact sums of DECIMAL and BIGINT columns)",
    "credential-name": "AIDP credential store entry holding the base64 service account key",
    "key-file": "a /Workspace/... key file instead of the credential store (not recommended)",
    "counts": "True = recount every verified table now",
    "external-tables": "True = also create external tables; only after their files are on OCI (transfer job)",
}


def _source(name: str) -> str:
    text = (HERE / name).read_text(encoding="utf-8")
    return "\n".join(line for line in text.splitlines() if not line.startswith("from gcp_aidp.dataplane"))


def _cell(kind: str, text: str) -> dict:
    cell = {"cell_type": kind, "metadata": {}, "source": text.splitlines(keepends=True)}
    if kind == "code":
        cell.update(execution_count=None, outputs=[])
    return cell


def notebook(stage: str, data_plan: dict) -> dict:
    module, title, params = STAGES[stage]
    stage_doc = _source(module).split('"""')[1].strip()
    param_lines = ["# ── PARAMETERS ──────────────────────────────────────────────────",
                   "# Edit these, or pass them as the job task's parameters (same names), which win.",
                   "PARAMS = {"]
    for key, value in {**params, "reports-dir": None}.items():
        note = _NOTES.get(key, "None = /Workspace/gcp-aidp-migration/reports" if key == "reports-dir" else "")
        param_lines.append(f"    {key!r}: {value!r},{'  # ' + note if note else ''}")
    param_lines.append("}")
    cells = [
        _cell("markdown", f"# {title}\n\n{stage_doc}\n\n---\n\n*Generated by `gcp-aidp migrate` from "
                          f"`gcp_aidp/dataplane/{module}`. Re-run `migrate` to regenerate; a hand edit is "
                          "overwritten.*"),
        _cell("code", "\n".join(param_lines)),
        _cell("code", "# ── DATA PLAN (from the approved migration plan) ──────────────\n"
                      f"import json\nDATA_PLAN = json.loads({json.dumps(json.dumps(data_plan))})\n"
                      "print(f\"plan {DATA_PLAN['plan_id']}: {len(DATA_PLAN['tables'])} tables, "
                      "{len(DATA_PLAN['views'])} views, catalog {DATA_PLAN['catalog']}\")"),
        _cell("markdown", "## Shared helpers"),
        _cell("code", _source("common.py")),
        _cell("markdown", "## Stage logic"),
        _cell("code", _source(module)),
        _cell("code", "# ── RUN ──────────────────────────────────────────────────────────\n"
                      "# Run every cell above first. main() returns the problems it found.\n"
                      "# Any problem fails the cell (and a job's task) with the problems in the\n"
                      "# error message; details are in the reports directory.\n"
                      "PARAMS = resolve_params(PARAMS)\n"
                      "problems = main(spark, PARAMS, DATA_PLAN)\n"
                      "if problems:\n"
                      "    print(f'\\n{len(problems)} problem(s):')\n"
                      "    for p in problems:\n"
                      "        print('  -', p)\n"
                      f"    raise RuntimeError(f'{stage}: {{len(problems)}} problem(s): ' + ' | '.join(problems)[:2000])\n"
                      f"print('{stage}: done, no problems')"),
    ]
    return {"cells": cells, "nbformat": 4, "nbformat_minor": 5,
            "metadata": {"gcp_aidp": {"generated": True, "stage": stage, "plan_id": data_plan["plan_id"]},
                         "kernelspec": {"display_name": "Python 3", "language": "python", "name": "python3"},
                         "language_info": {"name": "python"}}}


def data_plan(plan: dict, results: list[dict]) -> dict:
    """What the notebooks act on, from the plan and migrate's results."""
    by_id = {a["id"]: a for a in plan["assets"]}
    out = {"plan_id": plan.get("plan_id"), "project": plan.get("source_project"),
           "catalog": (plan.get("target") or {}).get("catalog"), "schemas": [], "tables": [], "views": [],
           "external_tables": [], "not_created": []}
    for r in results:
        a = by_id.get(r["asset_id"])
        if a is None or a["action"] != "MIGRATE":
            continue
        src, tgt = a["source"], a["target"]
        runnable = r["status"] in ("ok", "needs_manual_review")
        if src["type"] == "bq_dataset" and runnable:
            out["schemas"].append({"name": src["name"], "ddl": r["translated_sql"]})
        elif src["type"] == "bq_table":
            if runnable and r["translated_sql"]:
                out["tables"].append({
                    "dataset": src["dataset"], "name": src["name"],
                    "source": f"{plan.get('source_project')}.{src['dataset']}.{src['name']}",
                    "target": [tgt["catalog"], tgt["schema"], tgt["name"]], "ddl": r["translated_sql"],
                    "num_rows": src.get("num_rows"),
                    "columns": [{"name": c["name"], "source_type": c["source_type"],
                                 "target_type": c["target_type"]} for c in tgt["columns"]]})
            else:
                out["not_created"].append({"dataset": src["dataset"], "name": src["name"], "kind": "table",
                                           "verdict": "BLOCKED", "reason": _blocks(r)})
        elif src["type"] == "bq_view":
            if runnable and all(f["severity"] in ("rewrite", "caveat", "info") for f in r["findings"]):
                out["views"].append({"dataset": src["dataset"], "name": src["name"],
                                     "target": [tgt["catalog"], tgt["schema"], tgt["name"]],
                                     "ddl": r["translated_sql"]})
            else:
                out["not_created"].append({"dataset": src["dataset"], "name": src["name"], "kind": "view",
                                           "verdict": "BLOCKED" if r["status"] == "blocked" else "NEEDS_REVIEW",
                                           "reason": _blocks(r) or "flagged: review the artifact, then create it"})
        elif src["type"] == "bq_external_table":
            mapped = runnable and not any(f["rule"] == "GS01_BUCKET_MAP" and f["severity"] == "flag"
                                          for f in r["findings"])
            if mapped:
                out["external_tables"].append({"dataset": src["dataset"], "name": src["name"],
                                               "target": [tgt["catalog"], tgt["schema"], tgt["name"]],
                                               "ddl": r["translated_sql"]})
            else:
                out["not_created"].append({"dataset": src["dataset"], "name": src["name"], "kind": "external_table",
                                           "verdict": "BLOCKED", "reason": _blocks(r)})
        elif src["type"] == "bq_materialized_view":
            out["not_created"].append({"dataset": src["dataset"], "name": src["name"],
                                       "kind": "materialized_view", "verdict": "DEFERRED",
                                       "target": [tgt["catalog"], tgt["schema"], tgt["name"]],
                                       "reason": f"snapshot built by refresh job {tgt['refresh_job']} after the copy"})
    return out


def _blocks(result: dict) -> str:
    return "; ".join(f"{f['rule']}: {f['detail']}" for f in result.get("findings", [])
                     if f["severity"] in ("block", "flag"))


def write_notebooks(dp: dict, out_dir: Path) -> list[str]:
    from gcp_aidp._atomic import write_text_atomic

    paths = []
    for stage in STAGES:
        path = out_dir / "notebooks" / f"{stage}.ipynb"
        write_text_atomic(path, json.dumps(notebook(stage, dp), indent=1) + "\n")
        paths.append(path.relative_to(out_dir).as_posix())
    return paths


MIGRATION_JOB = "gcp_aidp_migration"


def sql_notebook(title: str, statements: list[str], plan_id: str) -> dict:
    """A notebook that runs `statements` in order: the task behind a refresh or scheduled-query job."""
    cells = [_cell("markdown", f"# {title}\n\n*Generated by `gcp-aidp migrate` (plan `{plan_id}`) from the "
                               "reviewed SQL artifact. Re-run `migrate` to regenerate.*")]
    cells += [_cell("code", f"spark.sql({json.dumps(s)})") for s in statements]
    return {"cells": cells, "nbformat": 4, "nbformat_minor": 5,
            "metadata": {"gcp_aidp": {"generated": True, "plan_id": plan_id},
                         "kernelspec": {"display_name": "Python 3", "language": "python", "name": "python3"},
                         "language_info": {"name": "python"}}}


def write_jobs(dp: dict, results: list[dict], out_dir: Path) -> list[dict]:
    """The AIDP jobs `publish` creates, unscheduled, with their task notebooks written here.

    `gcp_aidp_migration` chains the data-plane notebooks so `gcp-aidp run` can
    start the whole copy at once: diagnose, structure, one copy task per
    dataset, each materialized view's snapshot, reconcile. Each materialized
    view and scheduled query also gets a job of its own. Notebook paths are
    relative to `out_dir`; `publish` maps them to the workspace.
    """
    from gcp_aidp._atomic import write_text_atomic
    from gcp_aidp.plan.planner import job_name

    def task(key: str, notebook: str, **params) -> dict:
        return {"taskKey": job_name(key), "notebook": notebook,
                "parameters": [{"name": k, "value": v} for k, v in params.items()]}

    own, sql_tasks = [], []
    for r in results:
        job = r.get("job")
        if not job or r.get("status") not in ("ok", "needs_manual_review"):
            continue
        rel = f"notebooks/jobs/{job['name']}.ipynb"
        write_text_atomic(out_dir / rel, json.dumps(sql_notebook(job["title"], job["statements"], dp["plan_id"]),
                                                    indent=1) + "\n")
        own.append({"name": job["name"], "description": job["title"], "tasks": [task(job["name"], rel)]})
        if r["kind"] == "bq_materialized_view":
            sql_tasks.append(task(f"snapshot_{job['name']}", rel))

    datasets = sorted({t["dataset"] for t in dp["tables"]})
    chain = ([task("diagnose", "notebooks/00_diagnose.ipynb"), task("structure", "notebooks/01_structure.ipynb")]
             + [task(f"copy_{d}", "notebooks/02_copy_dataset.ipynb", dataset=d) for d in datasets]
             + sql_tasks + [task("reconcile", "notebooks/03_reconcile.ipynb")])
    for before, after in zip(chain, chain[1:]):  # one at a time: each step needs the one before
        after["dependsOn"] = [before["taskKey"]]
    migration = {"name": MIGRATION_JOB, "tasks": chain,
                 "description": f"Copy BigQuery project {dp['project']} into catalog {dp['catalog']} "
                                f"(plan {dp['plan_id']})."}
    return [migration] + own
